CREATE OR REPLACE VIEW public.library_tag_share AS WITH periods AS (SELECT 'current'::text period,NULL::timestamptz cutoff UNION ALL SELECT 'previous',now()-interval '28 days'), latest AS (SELECT DISTINCT ON(p.period,h.domain) p.period,h.* FROM periods p JOIN public.library_ai_tag_history h ON p.cutoff IS NULL OR h.captured_at<=p.cutoff ORDER BY p.period,h.domain,h.captured_at DESC,h.snapshot_id DESC), scoped AS (SELECT l.*,x.sector_group FROM latest l CROSS JOIN LATERAL(VALUES('all'::text),(l.sector)) x(sector_group) WHERE coalesce((l.tags->>'confidence')::numeric,0)>=0.4 AND coalesce(l.tags->>'low_confidence','false')<>'true' AND (l.tags->>'blocked_reason') IS NULL), totals AS (SELECT period,sector_group,count(*) sites FROM scoped GROUP BY period,sector_group), values AS (SELECT DISTINCT l.period,l.sector_group,l.domain,d.key dimension,v.value FROM scoped l CROSS JOIN LATERAL jsonb_each(l.tags) d CROSS JOIN LATERAL jsonb_array_elements_text(CASE WHEN jsonb_typeof(d.value)='array' THEN d.value WHEN jsonb_typeof(d.value)='string' THEN jsonb_build_array(d.value) ELSE '[]'::jsonb END) v(value) WHERE d.key IN ('imagery','aesthetic','components','hero_layout','ai_positioning','tone','color_mood')), counts AS (SELECT period,sector_group,dimension,value,count(*) n FROM values GROUP BY period,sector_group,dimension,value), keys AS(SELECT DISTINCT sector_group,dimension,value FROM counts) SELECT k.sector_group AS sector,k.dimension,k.value,coalesce(c.n,0) AS sites,t.sites AS tagged_sites,coalesce(c.n,0)::numeric/t.sites AS share,CASE WHEN pt.sites>0 THEN coalesce(pc.n,0)::numeric/pt.sites ELSE NULL END AS share_28d,CASE WHEN pt.sites>0 THEN (coalesce(c.n,0)::numeric/t.sites-coalesce(pc.n,0)::numeric/pt.sites)*100 ELSE NULL END AS delta_28d_pts FROM keys k JOIN totals t ON t.period='current' AND t.sector_group=k.sector_group LEFT JOIN counts c ON c.period='current' AND c.sector_group=k.sector_group AND c.dimension=k.dimension AND c.value=k.value LEFT JOIN totals pt ON pt.period='previous' AND pt.sector_group=k.sector_group LEFT JOIN counts pc ON pc.period='previous' AND pc.sector_group=k.sector_group AND pc.dimension=k.dimension AND pc.value=k.value;
GRANT SELECT ON public.library_tag_share TO anon,authenticated;